// ============================================
// DESCARGAR PDF ISO 9001 DESDE BACKBLAZE B2
// API nativa B2 — sin crypto, solo btoa()
// ============================================

const B2_KEY_ID  = $env.B2_KEY_ID;
const B2_APP_KEY = $env.B2_APP_KEY;
const B2_BUCKET  = $env.B2_BUCKET;
const FILE_KEY   = 'NOM_ISO_9001-2015.pdf';

const credentials = btoa(`${B2_KEY_ID}:${B2_APP_KEY}`);

const authResponse = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://api.backblazeb2.com/b2api/v3/b2_authorize_account',
  headers: { 'Authorization': `Basic ${credentials}` },
  json: true
});

const authToken   = authResponse.authorizationToken;
const downloadUrl = authResponse.apiInfo.storageApi.downloadUrl;

console.log(`✅ Auth OK — descargando ${FILE_KEY}...`);

const response = await this.helpers.httpRequest({
  method: 'GET',
  url: `${downloadUrl}/file/${B2_BUCKET}/${FILE_KEY}`,
  headers: { 'Authorization': authToken },
  encoding: 'arraybuffer',
  returnFullResponse: true
});

if (response.statusCode !== 200) {
  throw new Error(`Error al descargar de B2: ${response.statusCode} - ${JSON.stringify(response.body).slice(0,300)}`);
}

console.log(`✅ PDF descargado: ${response.body.byteLength} bytes`);

return [{
  json: { fileName: FILE_KEY },
  binary: {
    data: await this.helpers.prepareBinaryData(
      Buffer.from(response.body),
      FILE_KEY,
      'application/pdf'
    )
  }
}];

// ============================================
// PASO 1: CONCATENAR TODAS LAS PÁGINAS Y LIMPIAR
// extractFromFile devuelve 1 item por página — hay que unirlas
// ============================================

const allItems = $input.all();

console.log(`📄 Páginas recibidas: ${allItems.length}`);

// Concatenar texto de todas las páginas en orden
const fullText = allItems
  .map(item => item.json.text || '')
  .join('\n\n')
  .replace(/\r\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '')
  .trim();

if (!fullText || fullText.length < 100) {
  throw new Error('No se pudo extraer texto del PDF o el archivo está vacío');
}

console.log(`✅ Texto total concatenado: ${fullText.length} caracteres`);
console.log(`📊 Páginas procesadas: ${allItems.length}`);

// Retornar UN SOLO item con todo el texto
return [{
  json: {
    fullText,
    totalLength: fullText.length,
    totalPages: allItems.length,
    fileName: 'NOM_ISO_9001-2015',
    extractedAt: new Date().toISOString()
  }
}];

// ============================================
// DIVIDIR EN CHUNKS - chunkSize 800
// ============================================

const text = $input.item.json.fullText;
const totalPages = $input.item.json.totalPages || 42;

console.log(`📄 Texto recibido: ${text.length} caracteres, ${totalPages} páginas`);

const chunkSize = 800;
const overlap   = 120;

function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash).toString(16);
}

function detectClausula(texto) {
  const match = texto.match(/\b(\d+\.\d+(?:\.\d+)?)\s+([^\n]{5,100})/i);
  if (match) return { clausula: match[1], titulo: match[2].trim() };
  return { clausula: null, titulo: null };
}

function detectTipoRequisito(texto) {
  if (/\b(debe|deberá|tienen que|es necesario que)\b/i.test(texto)) return 'shall';
  if (/\b(debería|sería conveniente|es recomendable|se recomienda)\b/i.test(texto)) return 'should';
  if (/\b(puede|pueden|es posible|está permitido)\b/i.test(texto)) return 'can';
  return 'informativo';
}

// Dividir por párrafos Y por saltos de línea simples si los párrafos son muy largos
const chunks = [];
let currentChunk = '';
let lastClausula = null;
let lastTitulo = null;

// Primero intentar split por doble salto
let segments = text.split(/\n\n+/);

// Si hay muy pocos segmentos (PDF con poco espaciado), usar salto simple también
if (segments.length < 50) {
  console.log(`⚠️ Pocos párrafos (${segments.length}), usando salto simple también`);
  segments = text.split(/\n+/);
}

console.log(`📊 Segmentos para procesar: ${segments.length}`);

for (let i = 0; i < segments.length; i++) {
  const segment = segments[i].trim();
  if (!segment || segment.length < 5) continue;

  const clausulaInfo = detectClausula(segment);
  if (clausulaInfo.clausula) {
    lastClausula = clausulaInfo.clausula;
    lastTitulo   = clausulaInfo.titulo;
  }

  // Si el segmento solo ya supera chunkSize, dividirlo por palabras
  if (segment.length > chunkSize) {
    // Primero guardar lo que había acumulado
    if (currentChunk.trim()) {
      chunks.push({
        contenido:       currentChunk.trim(),
        clausula:        lastClausula,
        titulo_clausula: lastTitulo,
        tipo_requisito:  detectTipoRequisito(currentChunk)
      });
      currentChunk = '';
    }
    // Dividir el segmento largo en sub-chunks por palabras
    const words = segment.split(' ');
    let subChunk = '';
    for (const word of words) {
      if (subChunk.length + word.length + 1 > chunkSize && subChunk.length > 0) {
        chunks.push({
          contenido:       subChunk.trim(),
          clausula:        lastClausula,
          titulo_clausula: lastTitulo,
          tipo_requisito:  detectTipoRequisito(subChunk)
        });
        subChunk = subChunk.slice(-overlap) + ' ' + word;
      } else {
        subChunk += (subChunk ? ' ' : '') + word;
      }
    }
    if (subChunk.trim()) currentChunk = subChunk;
    continue;
  }

  if (currentChunk.length + segment.length + 2 > chunkSize && currentChunk.length > 0) {
    chunks.push({
      contenido:       currentChunk.trim(),
      clausula:        lastClausula,
      titulo_clausula: lastTitulo,
      tipo_requisito:  detectTipoRequisito(currentChunk)
    });
    currentChunk = currentChunk.slice(-overlap) + '\n' + segment;
  } else {
    currentChunk += (currentChunk ? '\n' : '') + segment;
  }
}

if (currentChunk.trim()) {
  chunks.push({
    contenido:       currentChunk.trim(),
    clausula:        lastClausula,
    titulo_clausula: lastTitulo,
    tipo_requisito:  detectTipoRequisito(currentChunk)
  });
}

const totalChunks = chunks.length;
console.log(`✅ Total chunks generados: ${totalChunks}`);
console.log(`📊 Con cláusula: ${chunks.filter(c => c.clausula).length}`);
console.log(`📏 Promedio chars por chunk: ${Math.round(chunks.reduce((a,c) => a + c.contenido.length, 0) / totalChunks)}`);

return chunks.map((chunk, idx) => ({
  json: {
    contenido:        chunk.contenido,
    chunk_index:      idx,
    total_chunks:     totalChunks,
    clausula:         chunk.clausula || 'sin_clasificar',
    titulo_clausula:  chunk.titulo_clausula || '',
    nivel_clausula:   chunk.clausula ? chunk.clausula.split('.').length : 0,
    tipo_requisito:   chunk.tipo_requisito,
    pagina:           Math.floor(idx / totalChunks * totalPages) + 1,
    version_norma:    '2015',
    hash_contenido:   simpleHash(chunk.contenido + idx.toString()),
    creado_por:       'sistema_ingesta',
    documento_origen: 'NOM_ISO_9001-2015'
  }
}));

// ============================================
// GENERAR EMBEDDINGS - OpenAI text-embedding-3-small (1536 dims)
// Mismo modelo usado en el flujo de capacitacion AVA
// ============================================

const OPENAI_API_KEY = $env.OPENAI_API_KEY;

const items = $input.all();
const results = [];

console.log(`🔄 Procesando ${items.length} chunks con OpenAI text-embedding-3-small...`);

// Procesar en lotes de 20 para no saturar la API
const BATCH_SIZE = 20;

for (let batchStart = 0; batchStart < items.length; batchStart += BATCH_SIZE) {
  const batch = items.slice(batchStart, batchStart + BATCH_SIZE);
  const textos = batch.map(item => item.json.contenido || '');

  // Filtrar vacíos pero mantener índices
  const validBatch = batch.filter(item => (item.json.contenido || '').length >= 10);
  const validTextos = validBatch.map(item => item.json.contenido);

  if (validTextos.length === 0) continue;

  console.log(`📦 Lote ${Math.floor(batchStart / BATCH_SIZE) + 1}: ${validTextos.length} chunks (${batchStart + 1}-${Math.min(batchStart + BATCH_SIZE, items.length)} de ${items.length})`);

  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.openai.com/v1/embeddings',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${OPENAI_API_KEY}`
      },
      body: {
        input: validTextos,
        model: 'text-embedding-3-small'
        // Sin 'dimensions' -> salida nativa de 1536 dims
      },
      json: true
    });

    // response.data es un array ordenado igual que validTextos
    for (let i = 0; i < validBatch.length; i++) {
      const item = validBatch[i].json;
      const embedding = response.data[i].embedding; // array de 1536 floats
      const embeddingVector = '[' + embedding.join(',') + ']';

      results.push({
        json: {
          contenido:       item.contenido,
          embedding_vector: embeddingVector,
          clausula:        item.clausula || 'sin_clasificar',
          titulo_clausula: item.titulo_clausula || '',
          nivel_clausula:  item.nivel_clausula || 0,
          tipo_requisito:  item.tipo_requisito || 'informativo',
          version_norma:   item.version_norma || '2015',
          pagina:          item.pagina || 0,
          chunk_index:     item.chunk_index || 0,
          total_chunks:    item.total_chunks || 0,
          hash_contenido:  item.hash_contenido || '',
          creado_por:      item.creado_por || 'sistema_ingesta'
        }
      });
    }

    console.log(`✅ Lote completado — ${results.length} embeddings generados hasta ahora`);

    // Pausa breve entre lotes para respetar rate limits
    if (batchStart + BATCH_SIZE < items.length) {
      await new Promise(resolve => setTimeout(resolve, 200));
    }

  } catch (error) {
    console.error(`❌ Error en lote ${Math.floor(batchStart / BATCH_SIZE) + 1}:`, error.message);
    // Intentar chunk a chunk si el lote falla
    console.log('🔁 Reintentando chunk a chunk...');
    for (const item of validBatch) {
      try {
        const r = await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://api.openai.com/v1/embeddings',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${OPENAI_API_KEY}`
          },
          body: { input: [item.json.contenido], model: 'text-embedding-3-small' },
          json: true
        });
        const embedding = r.data[0].embedding;
        results.push({
          json: {
            contenido:       item.json.contenido,
            embedding_vector: '[' + embedding.join(',') + ']',
            clausula:        item.json.clausula || 'sin_clasificar',
            titulo_clausula: item.json.titulo_clausula || '',
            nivel_clausula:  item.json.nivel_clausula || 0,
            tipo_requisito:  item.json.tipo_requisito || 'informativo',
            version_norma:   item.json.version_norma || '2015',
            pagina:          item.json.pagina || 0,
            chunk_index:     item.json.chunk_index || 0,
            total_chunks:    item.json.total_chunks || 0,
            hash_contenido:  item.json.hash_contenido || '',
            creado_por:      item.json.creado_por || 'sistema_ingesta'
          }
        });
        await new Promise(resolve => setTimeout(resolve, 100));
      } catch (err) {
        console.error(`❌ Fallo individual chunk ${item.json.chunk_index}:`, err.message);
      }
    }
  }
}

console.log(`\n🎉 Procesados ${results.length}/${items.length} chunks exitosamente`);

return results;

// ============================================
// INSERTAR EN SUPABASE — INSERT con ignore duplicates
// Tabla: iso9001_norma_duplicate (embedding vector(1536))
// ============================================

const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_KEY = $env.SUPABASE_KEY;

const item = $input.item.json;

console.log(`💾 Insertando chunk ${item.chunk_index}/${item.total_chunks} — cláusula: ${item.clausula}`);

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/iso9001_norma`,
    headers: {
      'Content-Type': 'application/json',
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Prefer': 'resolution=ignore-duplicates,return=minimal'
    },
    body: {
      contenido:       item.contenido,
      embedding:       item.embedding_vector,
      clausula:        item.clausula,
      titulo_clausula: item.titulo_clausula,
      nivel_clausula:  item.nivel_clausula,
      tipo_requisito:  item.tipo_requisito,
      version_norma:   item.version_norma,
      pagina:          item.pagina,
      chunk_index:     item.chunk_index,
      total_chunks:    item.total_chunks,
      hash_contenido:  item.hash_contenido,
      creado_por:      item.creado_por
    },
    json: true
  });

  console.log(`✅ Chunk ${item.chunk_index} insertado`);
  return { json: { success: true, chunk_index: item.chunk_index, clausula: item.clausula } };

} catch (error) {
  console.error(`⚠️ Error chunk ${item.chunk_index}: ${error.message}`);
  return { json: { success: false, chunk_index: item.chunk_index, error: error.message } };
}

// ============================================
// RESUMEN FINAL DE INGESTA
// ============================================

const allItems = $input.all();
const insertados = allItems.filter(item => item.json && item.json.success).length;

const clausulasUnicas = [...new Set(
  allItems
    .map(item => item.json.clausula)
    .filter(c => c && c !== 'sin_clasificar')
)];

const porTipoRequisito = allItems.reduce((acc, item) => {
  const tipo = item.json.tipo_requisito || 'desconocido';
  acc[tipo] = (acc[tipo] || 0) + 1;
  return acc;
}, {});

const resumen = {
  total_chunks: allItems.length,
  chunks_insertados: insertados,
  chunks_con_error: allItems.length - insertados,
  clausulas_identificadas: clausulasUnicas.length,
  lista_clausulas: clausulasUnicas.sort(),
  distribucion_requisitos: porTipoRequisito,
  timestamp: new Date().toISOString(),
  archivo: 'NOM_ISO_9001-2015',
  fuente: 'BackBlaze B2 (uniminuto-docs)',
  modelo_embeddings: 'text-embedding-3-small',
  dimensiones_embedding: 1536
};

console.log('\n📊 RESUMEN DE INGESTA ISO 9001:2015');
console.log('=====================================');
console.log(`✅ Chunks insertados: ${insertados}/${allItems.length}`);
console.log(`📝 Cláusulas identificadas: ${clausulasUnicas.length}`);
console.log(`⚡ Requisitos 'shall': ${porTipoRequisito.shall || 0}`);
console.log(`💡 Requisitos 'should': ${porTipoRequisito.should || 0}`);
console.log(`ℹ️  Informativos: ${porTipoRequisito.informativo || 0}`);
console.log(`🧠 Modelo: text-embedding-3-small (1536 dims)`);

return [{ json: resumen }];
